# Archive Reliability Dashboard demo: rollup of tool outputs into one view.
SERVICES={"search":{"avail":0.999,"p99":120,"integ":"clean"},
          "storage":{"avail":0.9999,"p99":60,"integ":"2 quarantined"},
          "indexer":{"avail":0.97,"p99":800,"integ":"clean"}}
def grade(s):
    if s["avail"]<0.99 or s["integ"]!="clean": return "DEGRADED"
    return "HEALTHY"
for name,s in SERVICES.items():
    print("%-8s %-8s avail=%.4f p99=%dms integrity=%s"%(name,grade(s),s["avail"],s["p99"],s["integ"]))
print("summary: storage and search healthy; indexer degraded - investigate before SLO breach")

